/**
 * Guided Azure portal walkthroughs for AI-200 (<PortalTour id="..." />).
 * Screens are simplified but follow the real portal's blade names and the
 * order of fields (checked on Microsoft Learn, 18 Nov 2026). Prices are
 * illustrative. Education only; nothing here talks to Azure.
 */
import type { Tour, Step, Group, Body, Screen, Field, Pane } from '../../lib/portal-tour';

/* ---------------- helpers ---------------- */
const HOME: Screen = { s: 'home' };
const RG = 'rg-ai-dev';
type Menu = (string | [string, string[]])[];

/** Home → search → pick a service. */
const find = (q: string, name: string, icon: string, sayHome: string, more: { g: string; n: string; i: string }[] = []): Step[] => [
  { sc: HOME, t: 'search', say: sayHome },
  { sc: { s: 'search', q, results: [{ g: 'Services', n: name, i: icon }, ...more] }, t: `res:${name}`, say: `Type **${q}** and pick **${name}** under *Services*.` },
];
const list = (title: string, i: string, cols: string[] = ['Type', 'Resource group', 'Location'], rows: string[][] = []): Screen => ({ s: 'list', title, i, cols, rows });
const wiz = (title: string, crumbs: string[], tabs: string[], tab: number, groups: Group[], intro?: string): Screen => ({ s: 'create', title, crumbs, tabs, tab, groups, intro, valid: tab === tabs.length - 1 });
const done = (name: string, say: string): Step => ({ sc: { s: 'deploy', name, done: true, rg: RG }, t: 'btn:Go to resource', say, toast: '✅ **Deployment succeeded**' });
const proj = (): Group => ({ h: 'Project details', f: [['Subscription *', 'Azure subscription 1'], ['Resource group *', RG, 's', 'Create new']] });
const summary = (rows: [string, string][]): Group[] => [{ h: 'Summary', f: rows.map(([k, v]) => [k, v, 'i'] as Field) }];

type ResBase = { title: string; type: string; i: string; menu: Menu; ess?: [string, string][]; cmds?: string[] };
/** Screen factory for one resource: blade name, body, command bar. */
const resOf = (b: ResBase) => (active: string, body?: Body[], cmds?: string[]): Screen => ({ s: 'res', title: b.title, type: b.type, i: b.i, menu: b.menu, crumbs: [RG], active, body, cmds: cmds ?? (active === 'Overview' ? b.cmds : undefined), ess: active === 'Overview' ? b.ess : undefined });

const form = (groups: Group[], save?: string, title?: string): Body => ({ b: 'form', groups, save, title });
const note = (text: string, tone: 'ok' | 'bad' | 'warn' | 'info' = 'info'): Body => ({ b: 'note', text, tone });
const code = (text: string, title?: string): Body => ({ b: 'code', text, title });
const tbl = (cols: string[], rows: string[][], title?: string, cmds?: string[]): Body => ({ b: 'table', cols, rows, title, cmds });
const sel = (l: string, v: string, n?: string): Field => (n ? [l, v, 's', n] : [l, v, 's']);
const txt = (l: string, v: string, n?: string): Field => (n ? [l, v, 't', n] : [l, v, 't']);
const ro = (l: string, v: string, n?: string): Field => (n ? [l, v, 'i', n] : [l, v, 'i']);
const pane = (title: string, groups: Group[], btns: string[], body?: Body[], sub?: string): Pane => ({ title, sub, groups, body, btns });

